template <typename Inst>
inline void execute_v_pk_add_f32_vop3p([[maybe_unused]] Inst &inst,
                                       [[maybe_unused]] Wavefront &wf) {
  ROCJITSU_TRY_SIMD_VOP3P_PK_BINARY_F32([](auto a, auto b) { return a + b; });
  uint64_t exec = dpp::execution_lane_mask(inst, wf);
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane))) {
      continue;
    }
    const auto s0_pair_w = amdgpu::RegisterAccess(wf).read_lane_pair32(inst.src0, lane);
    const uint32_t s0_lo_w = s0_pair_w.lo;
    const uint32_t s0_hi_w = s0_pair_w.hi;
    const auto s1_pair_w = amdgpu::RegisterAccess(wf).read_lane_pair32(inst.src1, lane);
    const uint32_t s1_lo_w = s1_pair_w.lo;
    const uint32_t s1_hi_w = s1_pair_w.hi;
    bool sel0_lo = (inst.inst_.op_sel >> 0) & 1;
    bool sel1_lo = (inst.inst_.op_sel >> 1) & 1;
    bool sel0_hi = (inst.inst_.op_sel_hi >> 0) & 1;
    bool sel1_hi = (inst.inst_.op_sel_hi >> 1) & 1;
    float a_lo = std::bit_cast<float>(sel0_lo ? s0_hi_w : s0_lo_w);
    float a_hi = std::bit_cast<float>(sel0_hi ? s0_hi_w : s0_lo_w);
    float b_lo = std::bit_cast<float>(sel1_lo ? s1_hi_w : s1_lo_w);
    float b_hi = std::bit_cast<float>(sel1_hi ? s1_hi_w : s1_lo_w);
    if (inst.inst_.neg & 1) {
      a_lo = -a_lo;
    }
    if (inst.inst_.neg & 2) {
      b_lo = -b_lo;
    }
    if (inst.inst_.neg_hi & 1) {
      a_hi = -a_hi;
    }
    if (inst.inst_.neg_hi & 2) {
      b_hi = -b_hi;
    }
    uint32_t rlo = amdgpu::fp_mode::packed_f32(
        a_lo, b_lo, 0.0f, amdgpu::fp_mode::PackedF32Op::ADD, wf.fp_round_mode_f32(),
        wf.fp_denorm_mode_f32(), inst.inst_.clamp, amdgpu::floating_clamp_nan_to_zero(wf),
        wf.cu().arch(), wf.ieee_mode());
    uint32_t rhi = amdgpu::fp_mode::packed_f32(
        a_hi, b_hi, 0.0f, amdgpu::fp_mode::PackedF32Op::ADD, wf.fp_round_mode_f32(),
        wf.fp_denorm_mode_f32(), inst.inst_.clamp, amdgpu::floating_clamp_nan_to_zero(wf),
        wf.cu().arch(), wf.ieee_mode());
    sdwa::write_lane64<amdgpu::sdwa::ResultFormat::F32>(
        inst, wf, inst.vdst, lane, static_cast<uint64_t>(rlo) | (static_cast<uint64_t>(rhi) << 32));
  }
}

template <typename Inst>
inline void execute_v_pk_fma_f32_vop3p([[maybe_unused]] Inst &inst,
                                       [[maybe_unused]] Wavefront &wf) {
  ROCJITSU_TRY_SIMD_VOP3P_PK_TERNARY_F32(
      [&wf](auto a, auto b, auto c) { return amdgpu::fma_f32_simd_unscoped(a, b, c, wf); });
  uint64_t exec = dpp::execution_lane_mask(inst, wf);
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane))) {
      continue;
    }
    const auto s0_pair_w = amdgpu::RegisterAccess(wf).read_lane_pair32(inst.src0, lane);
    const uint32_t s0_lo_w = s0_pair_w.lo;
    const uint32_t s0_hi_w = s0_pair_w.hi;
    const auto s1_pair_w = amdgpu::RegisterAccess(wf).read_lane_pair32(inst.src1, lane);
    const uint32_t s1_lo_w = s1_pair_w.lo;
    const uint32_t s1_hi_w = s1_pair_w.hi;
    const auto s2_pair_w = amdgpu::RegisterAccess(wf).read_lane_pair32(inst.src2, lane);
    const uint32_t s2_lo_w = s2_pair_w.lo;
    const uint32_t s2_hi_w = s2_pair_w.hi;
    bool sel0_lo = (inst.inst_.op_sel >> 0) & 1;
    bool sel1_lo = (inst.inst_.op_sel >> 1) & 1;
    bool sel2_lo = (inst.inst_.op_sel >> 2) & 1;
    bool sel0_hi = (inst.inst_.op_sel_hi >> 0) & 1;
    bool sel1_hi = (inst.inst_.op_sel_hi >> 1) & 1;
    bool sel2_hi = inst.inst_.op_sel_hi_2;
    float a_lo = std::bit_cast<float>(sel0_lo ? s0_hi_w : s0_lo_w);
    float a_hi = std::bit_cast<float>(sel0_hi ? s0_hi_w : s0_lo_w);
    float b_lo = std::bit_cast<float>(sel1_lo ? s1_hi_w : s1_lo_w);
    float b_hi = std::bit_cast<float>(sel1_hi ? s1_hi_w : s1_lo_w);
    float c_lo = std::bit_cast<float>(sel2_lo ? s2_hi_w : s2_lo_w);
    float c_hi = std::bit_cast<float>(sel2_hi ? s2_hi_w : s2_lo_w);
    if (inst.inst_.neg & 1) {
      a_lo = -a_lo;
    }
    if (inst.inst_.neg & 2) {
      b_lo = -b_lo;
    }
    if (inst.inst_.neg & 4) {
      c_lo = -c_lo;
    }
    if (inst.inst_.neg_hi & 1) {
      a_hi = -a_hi;
    }
    if (inst.inst_.neg_hi & 2) {
      b_hi = -b_hi;
    }
    if (inst.inst_.neg_hi & 4) {
      c_hi = -c_hi;
    }
    uint32_t rlo = amdgpu::fp_mode::packed_f32(
        a_lo, b_lo, c_lo, amdgpu::fp_mode::PackedF32Op::FMA, wf.fp_round_mode_f32(),
        wf.fp_denorm_mode_f32(), inst.inst_.clamp, amdgpu::floating_clamp_nan_to_zero(wf),
        wf.cu().arch(), wf.ieee_mode());
    uint32_t rhi = amdgpu::fp_mode::packed_f32(
        a_hi, b_hi, c_hi, amdgpu::fp_mode::PackedF32Op::FMA, wf.fp_round_mode_f32(),
        wf.fp_denorm_mode_f32(), inst.inst_.clamp, amdgpu::floating_clamp_nan_to_zero(wf),
        wf.cu().arch(), wf.ieee_mode());
    sdwa::write_lane64<amdgpu::sdwa::ResultFormat::F32>(
        inst, wf, inst.vdst, lane, static_cast<uint64_t>(rlo) | (static_cast<uint64_t>(rhi) << 32));
  }
}

